function panelHTML(){if(mode==='inspect')return `<h2>球種旋轉圖鑑。</h2><p class="play-intro-copy">點一種球，看看縫線往哪裡轉。</p><div class="pitch-catalog" aria-label="各球種旋轉">${pitchSpins.map(p=>`<button type="button" data-spin-pitch="${p.id}" aria-pressed="${inspectPitch===p.id}"><b>${p.name}</b><span>${p.rotation}</span></button>`).join('')}</div><p class="pitch-explanation" id="pitch-explanation">${pitchSpins.find(p=>p.id===inspectPitch).copy}</p><p class="pitch-note">這是常見旋轉的示意，每位投手會不同。轉速數字是可調的展示範例。</p><details class="ball-details"><summary>再看皮革與縫線 ＋</summary><div class="inspect-tools"><button type="button" data-inspect="seam" aria-pressed="${seamOn}">摸摸縫線 <span>01 ↗</span></button><button type="button" data-inspect="leather">靠近皮革 <span>02 ↗</span></button><button type="button" data-inspect="turn" aria-pressed="${auto}">${auto?'暫停旋轉':'開始旋轉'} <span>03 ↻</span></button></div><p class="play-callout" id="inspect-message" role="status">紅色針腳縫起兩片皮革。停下來、靠近一點看看。</p></details><button class="play-launch" type="button" id="inspect-next">去玩投球練習 ↗</button><details class="spin-sources"><summary>大人看：球種與資料來源</summary><p>旋轉軸與 RPM 用來示範，不是每種球唯一的數值。左右投以鏡像示意；本圖不模擬縫線尾流。<a href="https://rapsodo.com/blogs/baseball/understanding-rapsodo-pitching-data-spin-profile" target="_blank" rel="noopener">Rapsodo：旋轉方向與陀螺角</a>、<a href="https://rapsodo.com/blogs/baseball/understanding-rapsodo-pitching-data-spin-rate-efficiency-profile-curveball-slider-changeup/" target="_blank" rel="noopener">曲球、滑球、變速球</a>、<a href="https://rapsodo.com/blogs/baseball/understanding-rapsodo-pitching-data-spin-rate-efficiency-profile-fastball/" target="_blank" rel="noopener">直球家族</a>。</p></details>`;
return `<div class="pitch-deck"><div class="pitch-chips" role="group" aria-label="選球種">${pitchSpins.map(p=>`<button type="button" data-throw-pitch="${p.id}" aria-pressed="${throwPitch===p.id}"><b>${p.short}</b><small>${pitchDefaults[p.id].speed} km/h</small></button>`).join('')}<button type="button" data-throw-pitch="custom" aria-pressed="${throwPitch==='custom'}"><b>實驗</b><small>自訂旋轉</small></button></div><div class="pitch-row"><button type="button" class="hand-toggle" id="throw-hand" aria-label="切換左右投">${throwHand==='right'?'右投':'左投'} ⇄</button><label class="speed-compact"><span>速度 <output id="speed-value">${speed}</output> km/h</span><input id="play-speed" type="range" min="80" max="160" step="5" value="${speed}" aria-label="出手速度，公里每小時"></label></div><p id="throw-pitch-summary" class="throw-pitch-summary" role="status">${throwHint()}</p></div><div class="zone-console"><div class="zone-pad" id="zone-pad" role="application" aria-label="拖曳瞄準點，投手看出去的方向"><div class="zone-grid" aria-hidden="true">${'<i></i>'.repeat(9)}</div><div class="zone-goal" id="zone-goal" hidden></div><div class="zone-cursor" id="zone-cursor"><span>瞄準</span></div><span class="zone-tip">投手看出去 · 拖曳瞄準</span></div><div class="throw-block"><div class="meter" id="meter" aria-hidden="true"><div class="meter-good"></div><div class="meter-needle" id="meter-needle"></div></div><button class="play-launch" type="button" id="play-throw">${mode==='challenge'&&mission===3?'集滿了！再挑戰 ↻':'按住 → 放開投球'}</button><p class="meter-hint" id="meter-hint">針停在綠色區，球最準</p><div class="count" id="count">${countHTML()}</div></div></div><p class="play-result" id="play-result" role="status">${mode==='challenge'?'第 1 關：把瞄準點拖到金色圈，再按住投球。':'先拖曳瞄準點，再按住按鈕、看準綠色區放開。'}</p><details class="dock-more"><summary>更多設定 · 慢動作、重播、轉速</summary><div class="dock-more-content"><div class="play-action-options"><label><input id="play-slow" type="checkbox" ${slow?'checked':''}>慢動作 ×8</label><label><input id="play-big" type="checkbox" ${big?'checked':''}>球放大 2 倍</label><label><input id="play-compare" type="checkbox" ${compare?'checked':''}>灰球：不旋轉</label><label><input id="play-autocam" type="checkbox" ${autoCam?'checked':''}>自動跟拍</label></div><div class="play-action-options"><button class="quiet" type="button" id="play-pause" disabled>暫停</button><button class="quiet" type="button" id="play-replay" disabled>重播這一球 ↻</button><button class="quiet" id="aim-reset" type="button">瞄準回正中</button></div><div class="play-range"><label class="play-label" for="play-rpm">轉得多快 <output id="rpm-value">${throwRPM()} RPM</output></label><input class="play-slider" id="play-rpm" type="range" min="0" max="3600" step="10" value="${rpm}" ${throwPitch==='custom'&&spin==='none'?'disabled':''} aria-label="每分鐘旋轉圈數"></div><div class="play-aim" aria-label="微調瞄準點"><button type="button" data-aim="left" aria-label="瞄準向左">←</button><button type="button" data-aim="up" aria-label="瞄準向上">↑</button><span id="aim-value">${aimLabel()}</span><button type="button" data-aim="down" aria-label="瞄準向下">↓</button><button type="button" data-aim="right" aria-label="瞄準向右">→</button></div><div class="play-telemetry"><div><span>飛行時間</span><strong id="flight-time">—</strong></div><div><span>球的速度</span><strong id="flight-speed">—</strong></div><div><span>到目標距離</span><strong id="flight-distance">16.5 m</strong></div></div><div class="basic-spin-lab"><span>基本旋轉小實驗（會切到「實驗」球種）</span><div class="play-options" aria-label="投球旋轉">${Object.keys(spinTitles).map(x=>`<button type="button" data-pitch-spin="${x}" aria-pressed="${throwPitch==='custom'&&spin===x}">${spinTitles[x]}<small>${{back:'掉得少些',top:'掉得多些',side:'往旁邊彎',none:'仍受重力'}[x]}</small></button>`).join('')}</div></div></div></details>`;}
function countHTML(){const dots=(n,max)=>Array.from({length:max},(_,i)=>`<i class="${i<n?'on':''}"></i>`).join('');return `<span>好球 ${dots(count.s,2)}</span><span>壞球 ${dots(count.b,3)}</span><span class="tally">三振 ${count.outs} · 保送 ${count.walks}</span>`;}
function currentTarget(){return mode==='challenge'?targets[Math.min(mission,2)]:{x:target.x,y:target.y,radius:.2};}
function zoneCell(p){const col=-p.x<-.083?'左':-p.x>.083?'右':'中',row=p.y>ZONE.top-.19?'高':p.y<ZONE.bottom+.19?'低':'中';return row==='中'&&col==='中'?'正中央':col+row.replace('中','');}

function throwName(){return throwPitch==='custom'?spinTitles[spin]:pitchSpins.find(p=>p.id===throwPitch).name;}
function throwRPM(){return throwPitch==='custom'&&spin==='none'?0:rpm;}
function throwOptions(){const base=throwPitch!=='custom'?pitchFlightOptions(throwPitch,throwHand,{speed,rpm}):(()=>{const axis=[...F.axes[spin]];if(throwHand==='left'){axis[1]*=-1;axis[2]*=-1;}return {axis,speed,rpm:throwRPM()};})();return {...base,elevation,yaw,height:releasePoint.y};}
// Launch angles that send the chosen pitch to the aiming point; the player only picks where, like a game.
function solveAim(){let e=throwPitch!=='custom'?pitchDefaults[throwPitch].elevation:-1.7,y=0;for(let i=0;i<5;i++){const f=F.simulate({...throwOptions(),elevation:e,yaw:y});if(f.end.z<16.49){e+=2.5;continue;}e+=Math.atan2(target.y-f.end.y,16.5)*180/Math.PI;y+=Math.atan2(target.x-f.end.x,16.5)*180/Math.PI;}elevation=Math.round(e*100)/100;yaw=Math.round(y*100)/100;}
function throwHint(){
 if(throwPitch==='custom')return spinTitles[spin]+' · 用四種基本旋轉做實驗。';
 const p=pitchSpins.find(p=>p.id===throwPitch);
 return p.rotation+(p.id==='knuckle'?' · 示範低旋轉，不模擬亂流飄移。':' · 已套用示範值，方向與速度可以再調。');
}
function loadThrowPitch(id){throwPitch=id;if(id==='custom')return;const p=pitchFlightOptions(id,throwHand);speed=p.speed;rpm=p.rpm;}
function syncThrowChoices(){
 panel.querySelectorAll('[data-throw-pitch]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.throwPitch===throwPitch)));
 $('#throw-hand').textContent=(throwHand==='right'?'右投':'左投')+' ⇄';$('#throw-pitch-summary').textContent=throwHint();$('#play-speed').value=speed;$('#speed-value').textContent=speed;
 $('#play-rpm').value=rpm;$('#play-rpm').disabled=throwPitch==='custom'&&spin==='none';$('#rpm-value').textContent=throwRPM()+' RPM';
 panel.querySelectorAll('[data-pitch-spin]').forEach(b=>b.setAttribute('aria-pressed',String(throwPitch==='custom'&&b.dataset.pitchSpin===spin)));
 if($('#aim-value'))$('#aim-value').innerHTML=aimLabel();
}
function bindThrowChoices(){
 panel.querySelectorAll('[data-throw-pitch]').forEach(b=>b.onclick=()=>{loadThrowPitch(b.dataset.throwPitch);syncThrowChoices();resetShot();if(throwPitch==='custom')panel.querySelector('.dock-more').open=true;});
 $('#throw-hand').onclick=()=>{throwHand=throwHand==='right'?'left':'right';syncThrowChoices();resetShot();};
 $('#play-autocam').onchange=e=>{autoCam=e.target.checked;};
 bindZonePad();bindMeter();syncThrowChoices();
}
function placeCursor(){const c=$('#zone-cursor');if(!c)return;c.style.left=(.5-target.x/(2*PAD.x))*100+'%';c.style.top=(PAD.top-target.y)/(PAD.top-PAD.bottom)*100+'%';const g=$('#zone-goal');if(g){const t=targets[Math.min(mission,2)];g.hidden=mode!=='challenge'||mission===3;g.style.left=(.5-t.x/(2*PAD.x))*100+'%';g.style.top=(PAD.top-t.y)/(PAD.top-PAD.bottom)*100+'%';}}
function bindZonePad(){const pad=$('#zone-pad');if(!pad)return;let active=false;const move=e=>{const r=pad.getBoundingClientRect(),u=Math.min(1,Math.max(0,(e.clientX-r.left)/r.width)),v=Math.min(1,Math.max(0,(e.clientY-r.top)/r.height));target.x=Math.round(-(u-.5)*2*PAD.x*100)/100;target.y=Math.round((PAD.top-v*(PAD.top-PAD.bottom))*100)/100;updateGoal();updateAim();};
 pad.addEventListener('pointerdown',e=>{if(playing)return;active=true;pad.setPointerCapture(e.pointerId);move(e);});pad.addEventListener('pointermove',e=>{if(active)move(e);});pad.addEventListener('pointerup',()=>active=false);pad.addEventListener('pointercancel',()=>active=false);placeCursor();}
function bindMeter(){const b=$('#play-throw'),hint=$('#meter-hint');if(!b)return;
 const start=e=>{if(playing||(mode==='challenge'&&mission===3))return;meter.on=true;meter.pos=0;meter.dir=1;meter.down=performance.now();hint.textContent='放開！';b.classList.add('charging');e.preventDefault();try{b.setPointerCapture(e.pointerId);}catch{}};
 const stop=()=>{if(!meter.on)return;meter.on=false;b.classList.remove('charging');const tap=performance.now()-meter.down<160;meter.quality=tap?.35:Math.abs(meter.pos-.5)*2;hint.textContent=tap?'輕點：普通準度。按住再放開可以更準！':meter.quality<.18?'完美！':meter.quality<.45?'不錯！':'歪了一點…';launch(false);};
 b.addEventListener('pointerdown',start);b.addEventListener('pointerup',stop);b.addEventListener('pointercancel',()=>{meter.on=false;b.classList.remove('charging');hint.textContent='針停在綠色區，球最準';});b.addEventListener('contextmenu',e=>e.preventDefault());
 b.addEventListener('click',e=>{if(e.detail===0&&!meter.on){if(mode==='challenge'&&mission===3){mission=0;count={s:0,b:0,outs:0,walks:0};updateGoal();b.textContent='按住 → 放開投球';setResult('再來一輪。第 1 關：正中手套。');return;}meter.quality=.3;launch(false);}else if(mode==='challenge'&&mission===3){mission=0;updateGoal();b.textContent='按住 → 放開投球';setResult('再來一輪。第 1 關：正中手套。');}});
}
function setResult(text,success=false){const r=$('#play-result');if(r){r.textContent=text;r.classList.toggle('success',success);}fieldStatus.textContent=text;fieldStatus.classList.toggle('success',success);}
function aimLabel(){return '瞄準 '+zoneCell(target)+'<br>'+(Math.abs(target.x)<=ZONE.x&&target.y>=ZONE.bottom&&target.y<=ZONE.top?'好球帶內':'好球帶外');}
function adjustAim(direction){if(direction==='left')target.x=Math.min(PAD.x,target.x+.03);if(direction==='right')target.x=Math.max(-PAD.x,target.x-.03);if(direction==='up')target.y=Math.min(PAD.top,target.y+.03);if(direction==='down')target.y=Math.max(PAD.bottom,target.y-.03);target.x=Math.round(target.x*100)/100;target.y=Math.round(target.y*100)/100;updateGoal();updateAim();resetShot();}
